#include <stdio.h>

struct Node { int value; struct Node *next; };

int main(void)
{
    struct Node tail = {20, NULL};
    struct Node head = {10, &tail};
    printf("%d\n", head.next->value);
    return 0;
}

#include <stdio.h>

struct Node { int value; struct Node *next; };

int main(void)
{
    struct Node last = {30, NULL};
    struct Node first = {10, &last};
    struct Node *head = &first;
    head = head->next;
    printf("%d\n", head->value);
    return 0;
}

#include <stdio.h>

struct Node { int value; struct Node *next; };

int main(void)
{
    struct Node b = {8, NULL};
    struct Node a = {5, &b};
    int count = 0;
    for (struct Node *p = &a; p != NULL; p = p->next) {
        ++count;
    }
    printf("%d\n", count);
    return 0;
}
